def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Extend each row's marked cells between its leftmost and rightmost marks.
    for r in range(h):
        marks = [c for c in range(w) if grid[r][c] != background]
        if len(marks) >= 2:
            for c in range(min(marks), max(marks) + 1):
                if grid[r][c] == background:
                    out[r][c] = 3

    # Extend each column's marked cells between its topmost and bottommost marks.
    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] != background]
        if len(marks) >= 2:
            for r in range(min(marks), max(marks) + 1):
                if grid[r][c] == background:
                    out[r][c] = 3

    return out
